"""Existing players, real reload checkpoints and isolated negative UI fixtures."""
import json,time

def run(c,root,name,entry,checks,fixtures,completed,js,ck,wait,click,snapshot,follow,restore,shot):
 js('AL.UI.close();AL.Shell.close();AL.Store.close();window.existingBefore={credits:AL.game.credits,ids:AL.game.tanks.flatMap(t=>[...t.fish,...t.equipment].map(e=>e.id))}')
 click('#settings-button');click('#interactive-tutorial-settings [data-guide=restart]');click('[data-guide-confirm=restart]')
 follow('B-existing-player',limit=35)
 ck('B: existing player completes without repurchases or changed ownership',"AL.Tutorial.state(AL.game).status==='completed'&&AL.game.credits===existingBefore.credits&&JSON.stringify(AL.game.tanks.flatMap(t=>[...t.fish,...t.equipment].map(e=>e.id)))===JSON.stringify(existingBefore.ids)")
 ck('B: actual installed, prepared, cycled and feeding state is recognized',"['prepare','filter','controller','flow','cycle','stocking','feed','appetite'].every(id=>AL.Tutorial.state(AL.game).completed[id])")
 for phase,data in fixtures.items():
  restore(data);before=c.evaluate('({completed:Object.keys(AL.Tutorial.state(AL.game).completed),ids:AL.game.tanks.flatMap(t=>[...t.fish,...t.equipment,...AL.game.ownedEquipment].map(e=>e.id)),credits:AL.game.credits})')
  js("const result=AL.UI.save();if(!result.ok)throw Error(result.message)");c.navigate(entry,timeout=60);wait("!!window.AL?.game&&!!document.querySelector('[data-startup=continue]')")
  click('[data-startup=continue]');wait('!AL.Startup.pending&&!AL.Offline.busy')
  ck('C: '+phase+' reload retains every completed prerequisite',json.dumps(before['completed'])+".every(id=>AL.Tutorial.state(AL.game).completed[id])")
  ck('C: '+phase+' reload retains permanent identities and funds',"JSON.stringify(AL.game.tanks.flatMap(t=>[...t.fish,...t.equipment,...AL.game.ownedEquipment].map(e=>e.id)))==="+json.dumps(json.dumps(before['ids'],separators=(',',':')))+"&&AL.game.credits==="+str(before['credits']))
  expected="AL.TutorialUI.target?.dataset.waterStat==='ammonia'" if phase=='cycling' else "!!AL.Tutorial.state(AL.game).completed.substrate" if phase=='preparation' else "!!AL.Tutorial.state(AL.game).completed.filter" if phase=='installation' else "!!AL.Tutorial.resident(AL.game)"
  follow('C-'+phase,limit=35,until=expected)
  ck('C: '+phase+' resumes through the real highlighted route',expected)
  if phase in ['purchasing','receiving']:ck('C: '+phase+' creates one resident and one paid fish receipt',"AL.Tutorial.tank(AL.game).fish.length===1&&AL.game.finance.rows.filter(r=>r.action==='buyFish').length===1")
 restore(fixtures['receiving']);js("AL.Finance.change(AL.game,-AL.game.credits,{category:'other',action:'qa-spend',name:'Disposable test expense'})")
 js("AL.Store.open('fish','saltwater');AL.Store.details(AL.Tutorial.state(AL.game).productId);AL.TutorialUI.update()")
 ck('D: insufficient AC shows a blocked report and no free fish',"document.getElementById('confirm-fish').disabled&&AL.TutorialUI.target.id==='compatibility-report'&&document.getElementById('tutorial-tooltip').textContent.includes('AC')&&!AL.Tutorial.resident(AL.game)")
 restore(fixtures['receiving']);js("AL.Store.open('fish','saltwater');AL.Store.details(AL.Tutorial.state(AL.game).productId);AL.UI.close();AL.Store.close();AL.TutorialUI.update()")
 ck('D: closed purchase details cannot leave a stale hidden target',"AL.TutorialUI.target.getClientRects().length&&!document.getElementById('dialog').contains(AL.TutorialUI.target)")
 restore(fixtures['receiving']);js("AL.Tutorial.tank(AL.game).volume=20;AL.Store.open('fish','saltwater');AL.Store.details(AL.Tutorial.state(AL.game).productId);AL.TutorialUI.update()")
 ck('D: undersized tank blocks stocking using species volume',"document.getElementById('confirm-fish').disabled&&AL.Tutorial.report(AL.game).checks.some(c=>/volume/i.test(c.id)&&!c.ok)&&!AL.Tutorial.resident(AL.game)")
 restore(fixtures['receiving']);js("AL.Store.open('fish','saltwater');const p=AL.DailyStore.products(AL.game).find(p=>p.id===AL.Tutorial.state(AL.game).productId);AL.game.dailyStore.slots.find(x=>x.id===p.args.dailySlot).remaining=0;AL.Store.details(p.id);AL.TutorialUI.update()")
 ck('D: stock changed after browsing still blocks a stale offer',"document.getElementById('confirm-fish').disabled&&document.getElementById('compatibility-report').textContent.includes('stock')&&!AL.Tutorial.resident(AL.game)")
 restore(fixtures['installation']);js("const e=AL.game.ownedEquipment.find(e=>e.type==='filter');e.capacity=1;window.badEquipment=AL.Inventory.equipmentReport(AL.game,e,AL.Tutorial.tank(AL.game));AL.TutorialUI.update()")
 ck('D: incompatible physical equipment stays uninstalled',"!badEquipment.ok&&AL.game.ownedEquipment.some(e=>e.type==='filter')&&!AL.Tutorial.tank(AL.game).equipment.some(e=>e.type==='filter')")
 restore(fixtures['receiving']);js("AL.Tutorial.tank(AL.game).equipment.find(e=>e.type==='filter').enabled=false;AL.TutorialUI.update()")
 ck('D: lost filtration blocks stocking without resetting historical tasks',"!AL.Tutorial.report(AL.game).ok&&AL.Tutorial.state(AL.game).completed.filter&&AL.Tutorial.state(AL.game).completed.cycle")
 restore(fixtures['purchasing']);js("AL.Store.open('fish','saltwater');for(const n of document.querySelectorAll('[data-store-action=details]'))n.remove();AL.TutorialUI.update();window.missingCount=AL.Tutorial.state(AL.game).audit.filter(e=>e.kind==='missing-target').length;for(let i=0;i<5;i++)AL.TutorialUI.update()")
 ck('D: missing target has recovery and a bounded diagnostic',"document.getElementById('tutorial-tooltip').textContent.includes('not available')&&AL.Tutorial.state(AL.game).audit.filter(e=>e.kind==='missing-target').length===missingCount")
 js('AL.Store.close();AL.TutorialUI.update()')
 ck('D: closing a missing-target context recovers navigation',"AL.TutorialUI.target.dataset.page==='store'&&AL.Tutorial.state(AL.game).current==='details'")
 restore(fixtures['purchasing']);js("window.pinnedTank=AL.Tutorial.state(AL.game).tankId;AL.game=AL.Core.act(AL.game,'buyTank',{water:'marine',volume:75,kind:'reef',name:'Other test aquarium'});AL.UI.render();AL.TutorialUI.update()")
 ck('D: switching to a newly owned aquarium retains the pinned guide',"AL.game.selectedTank!==pinnedTank&&AL.Tutorial.state(AL.game).tankId===pinnedTank&&AL.TutorialUI.target.id==='aquarium-selector'")
 restore(fixtures['purchasing']);click('#ocean-diving');js('AL.TutorialUI.update()')
 ck('D: Ocean Diving interruption highlights its real close control',"document.getElementById('dialog').open&&AL.TutorialUI.target.id==='dialog-close'")
 click();js('AL.TutorialUI.update()')
 ck('D: returning from Ocean Diving retains the same objective',"AL.Tutorial.state(AL.game).current==='details'&&AL.TutorialUI.target.dataset.page==='store'")
 for w,h in [(1920,1080),(1600,900),(1366,768),(390,844)]:
  restore(fixtures['receiving']);c.call('Emulation.setDeviceMetricsOverride',{'width':w,'height':h,'deviceScaleFactor':1,'mobile':False})
  js("AL.Store.open('fish','saltwater');AL.Store.details(AL.Tutorial.state(AL.game).productId);AL.TutorialUI.update()");time.sleep(.15)
  ck(f'E: {w}x{h} tooltip stays visible',"(()=>{const r=document.getElementById('tutorial-tooltip').getBoundingClientRect();return r.left>=0&&r.top>=0&&r.right<=innerWidth&&r.bottom<=innerHeight})()")
  ck(f'E: {w}x{h} actual confirm is highlighted and enabled',"AL.TutorialUI.target.id==='confirm-fish'&&!AL.TutorialUI.target.disabled")
  ck(f'E: {w}x{h} page has no horizontal overflow',"document.documentElement.scrollWidth<=innerWidth")
  ck(f'E: {w}x{h} tooltip does not cover the confirmation button',"(()=>{const a=AL.TutorialUI.target.getBoundingClientRect(),b=document.getElementById('tutorial-tooltip').getBoundingClientRect();return Math.min(a.right,b.right)<=Math.max(a.left,b.left)||Math.min(a.bottom,b.bottom)<=Math.max(a.top,b.top)})()")
  ck(f'E: {w}x{h} price, quantity and destination form remain uncovered',"(()=>{const a=document.querySelector('[data-form=storePurchase]').getBoundingClientRect(),b=document.getElementById('tutorial-tooltip').getBoundingClientRect();return Math.min(a.right,b.right)<=Math.max(a.left,b.left)||Math.min(a.bottom,b.bottom)<=Math.max(a.top,b.top)})()")
  shot('purchase-'+str(w));click();wait('!!AL.Tutorial.resident(AL.game)')
  ck(f'E: {w}x{h} trusted pointer purchase successfully stocks one fish',"AL.Tutorial.tank(AL.game).fish.length===1")
